/// <param name="args">args</param>
[PostHandlerFor(classStr(SalesQuotationLineSalesPurchLine), methodStr(SalesQuotationLineSalesPurchLine, calcLineAmountForced))]
public static void SalesQuotationLineSalesPurchLine_Post_calcLineAmountForced(XppPrePostArgs args)
{
    SalesQuotationLineSalesPurchLine     salesQuotationLineSalesPurchLine = args.getThis();
    LineAmount                           lineAmount = args.getReturnValue();

    if (SalesQuotationLineSalesPurchLine.parmSalesPurchLine() is SalesQuotationLine)
    {
        SalesQuotationLine      salesQuotationLine = SalesQuotationLineSalesPurchLine.parmSalesPurchLine();

        if (salesQuotationLine.KCS_CRMisAlternativeLine)
        {
            lineAmount = 0;
        }
    }
    args.setReturnValue(lineAmount);
}
